// ── Main Page ──────────────────────────────────────────────────────────────────
const AssignProposal = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const { id } = useParams();

    const assignments = useSelector(s => s.proposals.items);
    const reviewersList = useSelector(s => s.reviewers.items);
    const assignment = assignments.find(a => String(a.id) === String(id));

    const [category, setCategory] = useState(CATEGORIES[0]);
    const [level, setLevel] = useState(assignment?.draftData?.category || 'UG');
    const [selectedReviewerId, setSelectedReviewerId] = useState(null);
    const [showConfirm, setShowConfirm] = useState(false);
    const [done, setDone] = useState(false);

    const title = assignment?.title ?? 'Untitled Proposal';
    const date = assignment?.date
        ? new Date(assignment.date).toLocaleDateString('en-GB', { day: 'numeric', month: 'numeric', year: 'numeric' })
        : 'No Assignment Date';

    const handleConfirm = () => {
        if (selectedReviewerId) {
            dispatch(assignReviewer({ assignmentId: Number(id), reviewerId: selectedReviewerId }));
        }
        setShowConfirm(false);
        setDone(true);
    };

    if (done) {
        return (
            <SuccessScreen
                title={title}
                date={date}
                onBack={() => navigate('/dashboard/assignments')}
            />
        );
    }

    return (
        <div className="min-h-screen bg-[#F3F4F6]">
            {/* Back button */}
            <button
                onClick={() => navigate(-1)}
                className="p-4 hover:bg-gray-200 rounded-full m-4 transition-colors inline-flex"
            >
                <ArrowLeft size={22} className="text-gray-800" />
            </button>

            <div className="max-w-2xl mx-auto px-6 pb-16">
                {/* Header */}
                <div className="mt-2 sm:mt-0">
                    <p className="text-[#003B95] font-black uppercase tracking-widest text-[10px] mb-2 sm:mb-1">You are about to assign...</p>
                    <h1 className="text-xl sm:text-2xl font-black text-gray-900 leading-tight mb-2 sm:mb-1 pr-4">{title}</h1>
                    <p className="text-xs sm:text-sm font-black text-gray-400 uppercase tracking-widest mb-8">{date}</p>
                </div>

                {/* Proposal categories + Level */}
                <div className="flex flex-col sm:flex-row gap-4 sm:gap-6 mb-10 w-full">
                    {/* Category dropdown */}
                    <div className="flex-1 w-full">
                        <label className="block text-xs font-black uppercase tracking-widest text-gray-800 mb-2">Proposal category</label>
                        <div className="relative">
                            <select
                                value={category}
                                onChange={e => setCategory(e.target.value)}
                                className="w-full appearance-none bg-[#F3F4F6] border border-gray-200 rounded-xl px-4 py-3 sm:py-3.5 pr-10 text-sm font-bold text-gray-800 outline-none focus:ring-2 focus:ring-[#003B95] transition-all shadow-sm"
                            >
                                {CATEGORIES.map(c => (
                                    <option key={c} value={c}>{c}</option>
                                ))}
                            </select>
                            <ChevronDown size={18} className="absolute right-3 top-1/2 -translate-y-1/2 text-[#003B95] pointer-events-none" />
                        </div>
                    </div>

                    {/* Level (read-only) */}
                    <div className="w-full sm:w-40 shrink-0">
                        <label className="block text-xs font-black uppercase tracking-widest text-gray-800 mb-2">Proposal Level</label>
                        <div className="bg-[#F3F4F6] border border-gray-200 rounded-xl px-4 py-3 sm:py-3.5 text-sm text-gray-800 font-bold shadow-sm">
                            {level}
                        </div>
                    </div>
                </div>

                {/* Assign Reviewer */}
                <div className="mb-8">
                    <h2 className="text-base font-bold text-gray-900 mb-3">Assign Reviewer</h2>

                    {/* Select Reviewer — functional dropdown */}
                    <div className="relative mb-4">
                        <select
                            value={selectedReviewerId ?? ''}
                            onChange={e => setSelectedReviewerId(e.target.value ? Number(e.target.value) : null)}
                            className="w-full appearance-none bg-[#E5E7EB] rounded-xl px-4 py-3 pr-10 text-sm text-gray-700 outline-none focus:ring-2 focus:ring-[#003B95] transition-all"
                        >
                            <option value="">Select Reviewer</option>
                            {reviewersList.map(r => (
                                <option key={r.id} value={r.id}>{r.name} — {r.specialization}</option>
                            ))}
                        </select>
                        <ChevronDown size={16} className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 pointer-events-none" />
                    </div>

                    {/* Reviewer list */}
                    <div className="space-y-px">
                        {reviewersList.map(r => (
                            <button
                                key={r.id}
                                onClick={() => setSelectedReviewerId(r.id)}
                                className={`w-full flex items-center justify-between px-4 py-4 transition-colors text-left rounded-lg ${selectedReviewerId === r.id
                                    ? 'bg-blue-50'
                                    : 'hover:bg-gray-100'
                                    }`}
                            >
                                <div>
                                    <p className="font-semibold text-gray-900 text-sm">{r.name}</p>
                                    <p className="text-xs text-[#003B95] mt-0.5">{r.ongoingAssignments || 0} assignments</p>
                                </div>
                                <div className="flex items-center gap-3">
                                    <span className="text-sm font-bold text-[#003B95]">{r.specialization}</span>
                                    {selectedReviewerId === r.id && (
                                        <Check size={16} className="text-[#003B95] shrink-0" />
                                    )}
                                </div>
                            </button>
                        ))}
                    </div>
                </div>

                {/* Assign button */}
                <div className="flex justify-center mt-8">
                    <button
                        onClick={() => selectedReviewerId && setShowConfirm(true)}
                        disabled={!selectedReviewerId}
                        className={`px-10 py-3 rounded-full font-bold text-sm transition-colors ${selectedReviewerId
                            ? 'bg-[#003B95] text-white hover:bg-blue-900'
                            : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                            }`}
                    >
                        Assign Assignment
                    </button>
                </div>
            </div>

            {/* Confirm modal */}
            {showConfirm && (
                <ConfirmModal
                    onClose={() => setShowConfirm(false)}
                    onConfirm={handleConfirm}
                />
            )}
        </div>
    );
};

export default AssignProposal;

import React, { useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { ArrowLeft } from 'lucide-react';
import { useSelector } from 'react-redux';

// Just grabbing the same list from Researchers.jsx for simplicity in this view
const DUMMY_RESEARCHERS = [
    { id: 1, name: 'Anaise Chem' },
    { id: 2, name: 'Ademide Sharon' },
    { id: 3, name: 'Amaka Hadiyat' },
    { id: 4, name: 'Balogun Fatima Ola' },
    { id: 5, name: 'Okafor Chinwe David' },
];

const TABS = ['Unaccepted', 'Not Reviewed', 'Ongoing', 'Completed'];

const ResearcherProposals = () => {
    const navigate = useNavigate();
    const { id } = useParams();
    const [activeTab, setActiveTab] = useState('Unaccepted');

    // Find researcher name
    const researcher = DUMMY_RESEARCHERS.find(r => r.id === Number(id));
    const researcherName = researcher ? researcher.name : 'Researcher';

    // Get all assignments from Redux (simulating researcher's proposals)
    const allAssignments = useSelector(s => s.proposals.items);
    const reviewers = useSelector(s => s.reviewers.items);

    // Filter assignments based on the active tab status AND researcher ID
    const proposals = allAssignments.filter(a => {
        // Filter by researcher if the assignment has a researcherId
        if (a.researcherId && a.researcherId !== Number(id)) return false;

        if (activeTab === 'Unaccepted') return a.status === 'Unaccepted';
        if (activeTab === 'Not Reviewed') return a.status === 'Not Reviewed';
        if (activeTab === 'Ongoing') return a.status === 'Ongoing';
        if (activeTab === 'Completed') return a.status === 'Completed';
        return true;
    });

    const getStatusColor = (status) => {
        switch (status) {
            case 'Unaccepted': return 'text-gray-500';
            case 'Not Reviewed': return 'text-[#C10000]';
            case 'Ongoing': return 'text-yellow-600';
            case 'Completed': return 'text-[#003B95]';
            default: return 'text-gray-500';
        }
    };

    const getStatusLabel = (status) => {
        switch (status) {
            case 'Unaccepted': return 'Unassigned';
            case 'Not Reviewed': return 'Review Rejected';
            case 'Ongoing': return 'Review Approved'; // Using 'Review Approved' (blue) based on screenshots context for ongoing/completed
            case 'Completed': return 'Completed';
            default: return status;
        }
    };

    const getButtonColor = (status) => {
        // In the screenshot: top button is blue (Unaccepted?), middle is green (Rejected review?), bottom is green (Approved review?)
        // We'll just map roughly: 'Not Reviewed'/Rejected -> green button, 'Ongoing'/Approved -> green button, Unaccepted -> blue button
        if (status === 'Unaccepted') return 'bg-[#003B95] hover:bg-blue-900';
        return 'bg-[#10B981] hover:bg-emerald-600'; // Green button for others
    };

    const statusTextColor = (status) => {
        if (status === 'Not Reviewed') return 'text-[#C10000]'; // Red "Review Rejected"
        if (status === 'Ongoing' || status === 'Completed') return 'text-[#003B95]'; // Blue "Review Approved"
        return '';
    }

    return (
        <div className="min-h-screen bg-[#F3F4F6] p-6">
            <div className="max-w-4xl mx-auto">
                {/* Header */}
                <div className="flex items-center gap-4 mb-8">
                    <button onClick={() => navigate(-1)} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
                        <ArrowLeft size={20} className="text-gray-800" />
                    </button>
                    <h1 className="text-xl font-bold text-gray-900">Researcher's Proposals</h1>
                </div>

                {/* Tabs - Scrollable on mobile */}
                <div className="mb-8 overflow-x-auto pb-2 no-scrollbar">
                    <div className="flex gap-2 bg-white/50 p-1.5 rounded-full inline-flex min-w-max">
                        {TABS.map(tab => (
                            <button
                                key={tab}
                                onClick={() => setActiveTab(tab)}
                                className={`px-5 py-2 rounded-full text-sm font-semibold transition-all whitespace-nowrap ${activeTab === tab
                                    ? 'bg-white shadow-sm text-gray-900'
                                    : 'text-gray-500 hover:text-gray-700 hover:bg-white/40'
                                    }`}
                            >
                                {tab}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Proposals List */}
                <div className="space-y-4">
                    {proposals.length === 0 ? (
                        <p className="text-gray-400 font-medium text-center py-10">No proposals in this category.</p>
                    ) : (
                        proposals.map(proposal => {
                            const reviewer = reviewers.find(r => r.id === proposal.reviewerId);

                            return (
                                <div key={proposal.id} className="bg-white rounded-2xl p-6 shadow-sm flex flex-col sm:flex-row items-start sm:items-center justify-between gap-5 transition-all hover:shadow-md">
                                    <div className="flex-1 min-w-0">
                                        {/* Status Label (e.g. Review Rejected / Review Approved) */}
                                        {proposal.status !== 'Unaccepted' && (
                                            <p className={`text-[10px] font-black uppercase tracking-[0.2em] mb-2 ${statusTextColor(proposal.status)}`}>
                                                {getStatusLabel(proposal.status)}
                                            </p>
                                        )}

                                        <h3 className="font-bold text-gray-900 text-base leading-tight mb-3">
                                            {proposal.title}
                                        </h3>

                                        {reviewer && (
                                            <div className="flex items-center gap-2 bg-gray-50 w-fit px-3 py-1.5 rounded-full border border-gray-100">
                                                <div className="w-6 h-6 rounded-full bg-[#003B95]/10 flex items-center justify-center text-[#003B95] font-bold text-[9px] overflow-hidden">
                                                    {reviewer.avatar ? <img src={reviewer.avatar} alt="R" className="w-full h-full object-cover" /> : reviewer.name.slice(0, 2).toUpperCase()}
                                                </div>
                                                <p className="text-xs text-gray-600 font-bold">{reviewer.name}</p>
                                            </div>
                                        )}
                                    </div>

                                    <button
                                        onClick={() => navigate(`/dashboard/assignments/${proposal.id}/view`)}
                                        className={`w-full sm:w-auto px-8 py-3 rounded-full text-white text-[11px] font-black uppercase tracking-widest transition-all shrink-0 shadow-sm active:scale-95 ${getButtonColor(proposal.status)}`}
                                    >
                                        View Details
                                    </button>
                                </div>
                            );
                        })
                    )}
                </div>
            </div>
        </div>
    );
};

export default ResearcherProposals;

import React, { useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useSelector, useDispatch } from 'react-redux';
import { updateReviewer, removeReviewer } from '../../features/reviewers/reviewersSlice';
import { ArrowLeft, MoreVertical, Mail, Phone, Building2, Award, Clock } from 'lucide-react';

const ReviewerProfile = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const dispatch = useDispatch();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [showDeactivateModal, setShowDeactivateModal] = useState(false);

  // Use Redux store instead of hardcoded data
  const reviewer = useSelector((s) =>
